type UserInfo struct {
	Token string `json:"token"`
	IoT   struct {
		User   string `json:"u"`
		Pass   string `json:"s"`
		Hash   string `json:"h"`
		Domain string `json:"k"`
		URL    struct {
			API  string `json:"a"`
			MQTT string `json:"m"`
		} `json:"r"`
	} `json:"rriot"`
}

func GetBaseURL(username string) (string, error) {
	u := "https://euiot.roborock.com/api/v1/getUrlByEmail?email=" + url.QueryEscape(username)
	req, err := http.NewRequest("POST", u, nil)
	if err != nil {
		return "", err
	}

	client := http.Client{Timeout: time.Second * 5000}
	res, err := client.Do(req)

	var v struct {
		Msg  string `json:"msg"`
		Code int    `json:"code"`
		Data struct {
			URL string `json:"url"`
		} `json:"data"`
	}
	if err = json.NewDecoder(res.Body).Decode(&v); err != nil {
		return "", err
	}

	if v.Code != 200 {
		return "", fmt.Errorf("%d: %s", v.Code, v.Msg)
	}

	return v.Data.URL, nil
}

func Login(baseURL, username, password string) (*UserInfo, error) {
	u := baseURL + "/api/v1/login?username=" + url.QueryEscape(username) +
		"&password=" + url.QueryEscape(password) + "&needtwostepauth=false"
	req, err := http.NewRequest("POST", u, nil)
	if err != nil {
		return nil, err
	}

	clientID := core.RandString(16, 64)
	clientID = base64.StdEncoding.EncodeToString([]byte(clientID))
	req.Header.Set("header_clientid", clientID)

	client := http.Client{Timeout: time.Second * 5000}
	res, err := client.Do(req)

	var v struct {
		Msg  string   `json:"msg"`
		Code int      `json:"code"`
		Data UserInfo `json:"data"`
	}
	if err = json.NewDecoder(res.Body).Decode(&v); err != nil {
		return nil, err
	}

	if v.Code != 200 {
		return nil, fmt.Errorf("%d: %s", v.Code, v.Msg)
	}

	return &v.Data, nil
}

func GetHomeID(baseURL, token string) (int, error) {
	req, err := http.NewRequest("GET", baseURL+"/api/v1/getHomeDetail", nil)
	if err != nil {
		return 0, err
	}
	req.Header.Set("Authorization", token)

	client := http.Client{Timeout: time.Second * 5000}
	res, err := client.Do(req)
	if err != nil {
		return 0, err
	}

	var v struct {
		Msg  string `json:"msg"`
		Code int    `json:"code"`
		Data struct {
			HomeID int `json:"rrHomeId"`
		} `json:"data"`
	}
	if err = json.NewDecoder(res.Body).Decode(&v); err != nil {
		return 0, err
	}

	if v.Code != 200 {
		return 0, fmt.Errorf("%d: %s", v.Code, v.Msg)
	}

	return v.Data.HomeID, nil
}

type DeviceInfo struct {
	DID  string `json:"duid"`
	Name string `json:"name"`
	Key  string `json:"localKey"`
}

func GetDevices(ui *UserInfo, homeID int) ([]DeviceInfo, error) {
	nonce := core.RandString(6, 64)
	ts := time.Now().Unix()
	path := "/user/homes/" + strconv.Itoa(homeID)

	mac := fmt.Sprintf(
		"%s:%s:%s:%d:%x::", ui.IoT.User, ui.IoT.Pass, nonce, ts, md5.Sum([]byte(path)),
	)
	hash := hmac.New(sha256.New, []byte(ui.IoT.Hash))
	hash.Write([]byte(mac))
	mac = base64.StdEncoding.EncodeToString(hash.Sum(nil))

	auth := fmt.Sprintf(
		`Hawk id="%s", s="%s", ts="%d", nonce="%s", mac="%s"`,
		ui.IoT.User, ui.IoT.Pass, ts, nonce, mac,
	)

	req, err := http.NewRequest("GET", ui.IoT.URL.API+path, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", auth)

	client := http.Client{Timeout: time.Second * 5000}
	res, err := client.Do(req)
	if err != nil {
		return nil, err
	}

	var v struct {
		Result struct {
			Devices []DeviceInfo `json:"devices"`
		} `json:"result"`
	}
	if err = json.NewDecoder(res.Body).Decode(&v); err != nil {
		return nil, err
	}

	return v.Result.Devices, nil
}

package wyoming

import (
	"bufio"
	"encoding/json"
	"io"
	"net"

	"github.com/AlexxIT/go2rtc/pkg/core"
)

type API struct {
	conn net.Conn
	rd   *bufio.Reader
}

func DialAPI(address string) (*API, error) {
	conn, err := net.DialTimeout("tcp", address, core.ConnDialTimeout)
	if err != nil {
		return nil, err
	}

	return NewAPI(conn), nil
}

const Version = "1.5.4"

func NewAPI(conn net.Conn) *API {
	return &API{conn: conn, rd: bufio.NewReader(conn)}
}

func (w *API) WriteEvent(evt *Event) (err error) {
	hdr := EventHeader{
		Type:          evt.Type,
		Version:       Version,
		DataLength:    len(evt.Data),
		PayloadLength: len(evt.Payload),
	}

	buf, err := json.Marshal(hdr)
	if err != nil {
		return err
	}

	buf = append(buf, '\n')
	buf = append(buf, evt.Data...)
	buf = append(buf, evt.Payload...)

	_, err = w.conn.Write(buf)
	return err
}

func (w *API) ReadEvent() (*Event, error) {
	data, err := w.rd.ReadBytes('\n')
	if err != nil {
		return nil, err
	}

	var hdr EventHeader
	if err = json.Unmarshal(data, &hdr); err != nil {
		return nil, err
	}

	evt := Event{Type: hdr.Type}

	if hdr.DataLength > 0 {
		data = make([]byte, hdr.DataLength)
		if _, err = io.ReadFull(w.rd, data); err != nil {
			return nil, err
		}
		evt.Data = string(data)
	}

	if hdr.PayloadLength > 0 {
		evt.Payload = make([]byte, hdr.PayloadLength)
		if _, err = io.ReadFull(w.rd, evt.Payload); err != nil {
			return nil, err
		}
	}

	return &evt, nil
}

func (w *API) Close() error {
	return w.conn.Close()
}

type Event struct {
	Type    string
	Data    string
	Payload []byte
}

type EventHeader struct {
	Type          string `json:"type"`
	Version       string `json:"version"`
	DataLength    int    `json:"data_length,omitempty"`
	PayloadLength int    `json:"payload_length,omitempty"`
}

